def compute(vars):
    denominator = vars["v2"]
    if denominator == 0:
        return None

    value = (vars["v1"] / denominator) * 100

    return {
        "value": value,
        "trace": {
            "leasehold_improvements": vars["v1"],
            "property_equipment_before_accumulated_depreciation_and_amortization": denominator,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
